<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');
require_once __DIR__.'/../config/auth.php';
$config=require __DIR__.'/../config/database.php';
$pdo=new PDO("mysql:host={$config['host']};dbname={$config['dbname']};charset={$config['charset']}",$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
function out(array $d,int $c=200):never{http_response_code($c);echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function siteId(PDO $pdo,string $clave):string{$st=$pdo->prepare("SELECT id FROM sedes WHERE clave=:c AND activo=1 LIMIT 1");$st->execute([':c'=>$clave]);$id=(string)$st->fetchColumn();if(!$id)out(['ok'=>false,'error'=>'Sede inválida'],422);return $id;}
function generarSesiones(PDO $pdo,string $fecha,string $uid,string $sedeId):int{
 $sql="SELECT DISTINCT h.id,h.hora_inicio FROM horarios h WHERE h.sede_id=:s AND h.activo=1 AND (EXISTS(SELECT 1 FROM alumnos a WHERE a.sede_id=:sa AND a.horario_preferido_id=h.id AND a.estado_administrativo IN ('ACTIVO','PENDIENTE')) OR EXISTS(SELECT 1 FROM curso_intensivo_alumnos cia JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.horario_id=h.id AND ci.sede_id=:sc AND ci.estado IN ('PROGRAMADO','EN_CURSO') AND :f BETWEEN ci.fecha_inicio AND ci.fecha_fin)) ORDER BY h.hora_inicio";
 $st=$pdo->prepare($sql);$st->execute([':s'=>$sedeId,':sa'=>$sedeId,':sc'=>$sedeId,':f'=>$fecha]);$horarios=$st->fetchAll();$n=0;
 foreach($horarios as $h){$q=$pdo->prepare("SELECT id FROM sesiones WHERE fecha=:f AND horario_id=:h LIMIT 1");$q->execute([':f'=>$fecha,':h'=>$h['id']]);if($q->fetch())continue;$bloque=((int)substr((string)$h['hora_inicio'],0,2)<12)?'AM':'PM';$q=$pdo->prepare("INSERT INTO sesiones(fecha,bloque,horario_id,created_by) VALUES(:f,:b,:h,:u)");$q->execute([':f'=>$fecha,':b'=>$bloque,':h'=>$h['id'],':u'=>$uid]);$n++;}
 return $n;
}
function alumnosSesion(PDO $pdo,array $s,string $fecha,string $sedeId):array{
 if(!$s['horario_id'])return [];
 $q=$pdo->prepare("SELECT a.id,a.nombre,a.estado_administrativo,p.sesiones_semana,m.estado mensualidad_estado,aa.estado asistencia_estado,aa.observacion,EXISTS(SELECT 1 FROM curso_intensivo_alumnos cia JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.alumno_id=a.id AND cia.horario_id=:h1 AND ci.sede_id=:sc1 AND ci.estado IN ('PROGRAMADO','EN_CURSO') AND :f1 BETWEEN ci.fecha_inicio AND ci.fecha_fin) intensivo_activo,(SELECT cia.curso_intensivo_id FROM curso_intensivo_alumnos cia JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.alumno_id=a.id AND cia.horario_id=:h2 AND ci.sede_id=:sc2 AND ci.estado IN ('PROGRAMADO','EN_CURSO') AND :f2 BETWEEN ci.fecha_inicio AND ci.fecha_fin LIMIT 1) curso_intensivo_id FROM alumnos a LEFT JOIN planes p ON p.id=a.plan_actual_id LEFT JOIN mensualidades m ON m.alumno_id=a.id AND m.sede_id=:sm AND m.mes=MONTH(:f3) AND m.anio=YEAR(:f4) LEFT JOIN asistencias aa ON aa.sesion_id=:sid AND aa.alumno_id=a.id WHERE a.sede_id=:sa AND ((a.horario_preferido_id=:h3 AND a.estado_administrativo IN ('ACTIVO','PENDIENTE')) OR EXISTS(SELECT 1 FROM curso_intensivo_alumnos cia2 JOIN cursos_intensivos ci2 ON ci2.id=cia2.curso_intensivo_id WHERE cia2.alumno_id=a.id AND cia2.horario_id=:h4 AND ci2.sede_id=:sc3 AND ci2.estado IN ('PROGRAMADO','EN_CURSO') AND :f5 BETWEEN ci2.fecha_inicio AND ci2.fecha_fin)) ORDER BY a.nombre");
 $q->execute([':h1'=>$s['horario_id'],':sc1'=>$sedeId,':f1'=>$fecha,':h2'=>$s['horario_id'],':sc2'=>$sedeId,':f2'=>$fecha,':sm'=>$sedeId,':f3'=>$fecha,':f4'=>$fecha,':sid'=>$s['id'],':sa'=>$sedeId,':h3'=>$s['horario_id'],':h4'=>$s['horario_id'],':sc3'=>$sedeId,':f5'=>$fecha]);$rows=$q->fetchAll();foreach($rows as &$a){$a['puede_tomar_clase']=((int)$a['intensivo_activo']===1)||($a['estado_administrativo']==='ACTIVO'&&$a['mensualidad_estado']==='PAGADA');}unset($a);return $rows;
}
function sincronizarReposicion(PDO $pdo,string $sid,string $aid,string $estado,string $uid):array{
 $st=$pdo->prepare("SELECT s.fecha,a.plan_actual_id,p.sesiones_semana,(SELECT cia.id FROM curso_intensivo_alumnos cia JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.alumno_id=a.id AND ci.estado IN ('PROGRAMADO','EN_CURSO') AND s.fecha BETWEEN ci.fecha_inicio AND ci.fecha_fin LIMIT 1) cia_id,(SELECT cia.curso_intensivo_id FROM curso_intensivo_alumnos cia JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.alumno_id=a.id AND ci.estado IN ('PROGRAMADO','EN_CURSO') AND s.fecha BETWEEN ci.fecha_inicio AND ci.fecha_fin LIMIT 1) curso_id FROM sesiones s JOIN alumnos a ON a.id=:a LEFT JOIN planes p ON p.id=a.plan_actual_id WHERE s.id=:s LIMIT 1");$st->execute([':a'=>$aid,':s'=>$sid]);$x=$st->fetch();if(!$x)return ['generada'=>false];
 $st=$pdo->prepare("SELECT id FROM asistencias WHERE sesion_id=:s AND alumno_id=:a LIMIT 1");$st->execute([':s'=>$sid,':a'=>$aid]);$asistencia=(string)$st->fetchColumn();
 if($x['cia_id']){if($estado==='AUSENTE_JUSTIFICADA'){$id=(string)$pdo->query("SELECT UUID()")->fetchColumn();$st=$pdo->prepare("INSERT IGNORE INTO ausencias(id,intensivo_id,alumno_id,fecha,motivo) VALUES(:id,:c,:a,:f,:m)");$st->execute([':id'=>$id,':c'=>$x['curso_id'],':a'=>$aid,':f'=>$x['fecha'],':m'=>'Ausencia justificada en sesión']);$n=$st->rowCount();if($n){$st=$pdo->prepare("UPDATE curso_intensivo_alumnos SET reposiciones_justificadas=LEAST(reposiciones_justificadas+1,5) WHERE id=:id");$st->execute([':id'=>$x['cia_id']]);}return ['generada'=>$n>0,'tipo'=>'INTENSIVO','limite'=>5];}$st=$pdo->prepare("DELETE FROM ausencias WHERE intensivo_id=:c AND alumno_id=:a AND fecha=:f AND motivo='Ausencia justificada en sesión'");$st->execute([':c'=>$x['curso_id'],':a'=>$aid,':f'=>$x['fecha']]);if($st->rowCount()){$st=$pdo->prepare("UPDATE curso_intensivo_alumnos SET reposiciones_justificadas=GREATEST(reposiciones_justificadas-1,0) WHERE id=:id");$st->execute([':id'=>$x['cia_id']]);}return ['generada'=>false,'tipo'=>'INTENSIVO'];}
 if(!$asistencia)return ['generada'=>false];if($estado!=='AUSENTE_JUSTIFICADA'){$st=$pdo->prepare("UPDATE reposiciones_regulares SET estado='CANCELADA' WHERE ausencia_asistencia_id=:aus AND estado='DISPONIBLE'");$st->execute([':aus'=>$asistencia]);return ['generada'=>false,'tipo'=>'REGULAR'];}if((int)$x['sesiones_semana']!==3)return ['generada'=>false,'motivo'=>'El plan no genera reposiciones'];$st=$pdo->prepare("SELECT id,estado FROM reposiciones_regulares WHERE ausencia_asistencia_id=:aus LIMIT 1");$st->execute([':aus'=>$asistencia]);$exist=$st->fetch();if($exist&&$exist['estado']==='DISPONIBLE')return ['generada'=>false,'tipo'=>'REGULAR','ya_existia'=>true];$st=$pdo->prepare("SELECT COUNT(*) FROM reposiciones_regulares rr JOIN asistencias aa ON aa.id=rr.ausencia_asistencia_id JOIN sesiones s ON s.id=aa.sesion_id WHERE rr.alumno_id=:a AND YEAR(s.fecha)=YEAR(:f1) AND MONTH(s.fecha)=MONTH(:f2) AND rr.estado IN ('DISPONIBLE','USADA')");$st->execute([':a'=>$aid,':f1'=>$x['fecha'],':f2'=>$x['fecha']]);if((int)$st->fetchColumn()>=2)return ['generada'=>false,'motivo'=>'Ya alcanzó 2 reposiciones del mes'];if($exist){$st=$pdo->prepare("UPDATE reposiciones_regulares SET estado='DISPONIBLE',sesion_reposicion_id=NULL,used_at=NULL WHERE id=:id");$st->execute([':id'=>$exist['id']]);return ['generada'=>true,'tipo'=>'REGULAR','limite'=>2];}$id=(string)$pdo->query("SELECT UUID()")->fetchColumn();$st=$pdo->prepare("INSERT INTO reposiciones_regulares(id,alumno_id,ausencia_asistencia_id,created_by) VALUES(:id,:a,:aus,:u)");$st->execute([':id'=>$id,':a'=>$aid,':aus'=>$asistencia,':u'=>$uid]);return ['generada'=>true,'tipo'=>'REGULAR','limite'=>2];
}
try{
 $method=$_SERVER['REQUEST_METHOD']??'GET';
 if($method==='GET'){$me=auth_require(['ADMIN','VERIFICADOR']);$clave=auth_resolve_sede_clave((string)($_GET['sede']??'MONTEVERDE'));$sedeId=siteId($pdo,$clave);$fecha=(string)($_GET['fecha']??date('Y-m-d'));$uid=(string)$me['id'];$creadas=($me['rol']==='ADMIN')?generarSesiones($pdo,$fecha,$uid,$sedeId):0;$stmt=$pdo->prepare("SELECT s.id,s.fecha,s.bloque,s.horario_id,s.estado,s.cerrada,s.motivo_cancelacion,h.hora_inicio,h.hora_fin FROM sesiones s JOIN horarios h ON h.id=s.horario_id WHERE s.fecha=:f AND h.sede_id=:site ORDER BY h.hora_inicio,s.bloque");$stmt->execute([':f'=>$fecha,':site'=>$sedeId]);$sesiones=$stmt->fetchAll();foreach($sesiones as &$s)$s['alumnos']=alumnosSesion($pdo,$s,$fecha,$sedeId);unset($s);out(['ok'=>true,'fecha'=>$fecha,'sede'=>$clave,'sesiones_creadas'=>$creadas,'sesiones'=>$sesiones]);}
 $me=auth_require(['ADMIN']);if($method!=='POST')out(['ok'=>false,'error'=>'Método no permitido'],405);$in=json_decode(file_get_contents('php://input'),true)?:[];$clave=auth_resolve_sede_clave((string)($in['sede']??'MONTEVERDE'));$sedeId=siteId($pdo,$clave);$uid=(string)$me['id'];$accion=strtoupper((string)($in['accion']??''));
 if($accion==='GENERAR'){$fecha=(string)($in['fecha']??date('Y-m-d'));out(['ok'=>true,'creadas'=>generarSesiones($pdo,$fecha,$uid,$sedeId)]);}
 if($accion==='ASISTENCIA'){$sid=(string)($in['sesion_id']??'');$aid=(string)($in['alumno_id']??'');$estado=(string)($in['estado']??'');if(!in_array($estado,['PRESENTE','AUSENTE_JUSTIFICADA','AUSENTE_NO_JUSTIFICADA'],true))out(['ok'=>false,'error'=>'Estado inválido'],422);$scope=$pdo->prepare("SELECT 1 FROM sesiones s JOIN horarios h ON h.id=s.horario_id JOIN alumnos a ON a.id=:a WHERE s.id=:ss AND h.sede_id=:sh AND a.sede_id=:sa LIMIT 1");$scope->execute([':a'=>$aid,':ss'=>$sid,':sh'=>$sedeId,':sa'=>$sedeId]);if(!$scope->fetchColumn())out(['ok'=>false,'error'=>'Sesión o alumno fuera de la sede seleccionada'],403);$check=$pdo->prepare("SELECT a.estado_administrativo,m.estado mensualidad_estado,EXISTS(SELECT 1 FROM curso_intensivo_alumnos cia JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id JOIN sesiones s ON s.id=:s1 WHERE cia.alumno_id=a.id AND cia.horario_id=s.horario_id AND ci.sede_id=:site1 AND ci.estado IN ('PROGRAMADO','EN_CURSO') AND s.fecha BETWEEN ci.fecha_inicio AND ci.fecha_fin) intensivo FROM alumnos a JOIN sesiones s2 ON s2.id=:s2 LEFT JOIN mensualidades m ON m.alumno_id=a.id AND m.sede_id=:site2 AND m.mes=MONTH(s2.fecha) AND m.anio=YEAR(s2.fecha) WHERE a.id=:a LIMIT 1");$check->execute([':s1'=>$sid,':site1'=>$sedeId,':s2'=>$sid,':site2'=>$sedeId,':a'=>$aid]);$ac=$check->fetch();$puede=$ac&&(((int)$ac['intensivo']===1)||($ac['estado_administrativo']==='ACTIVO'&&$ac['mensualidad_estado']==='PAGADA'));if(!$puede)out(['ok'=>false,'error'=>'El alumno no tiene derecho a tomar esta clase'],422);$pdo->beginTransaction();$st=$pdo->prepare("INSERT INTO asistencias(sesion_id,alumno_id,estado,observacion,created_by) VALUES(:s,:a,:e,:o,:u) ON DUPLICATE KEY UPDATE estado=VALUES(estado),observacion=VALUES(observacion),updated_at=NOW()");$st->execute([':s'=>$sid,':a'=>$aid,':e'=>$estado,':o'=>($in['observacion']??null),':u'=>$uid]);$repo=sincronizarReposicion($pdo,$sid,$aid,$estado,$uid);$pdo->commit();out(['ok'=>true,'reposicion'=>$repo]);}
 if($accion==='CERRAR'){$sid=(string)($in['sesion_id']??'');$st=$pdo->prepare("UPDATE sesiones s JOIN horarios h ON h.id=s.horario_id SET s.estado='REALIZADA',s.cerrada=1,s.fecha_cierre=NOW(),s.cerrada_por=:u WHERE s.id=:ss AND h.sede_id=:site AND s.cerrada=0");$st->execute([':u'=>$uid,':ss'=>$sid,':site'=>$sedeId]);out(['ok'=>true]);}
 out(['ok'=>false,'error'=>'Acción inválida'],422);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();out(['ok'=>false,'error'=>$e->getMessage()],500);}